const button=(label,action,cls='',id='')=>'<button class="'+cls+'" data-action="'+action+'"'+(id?' data-id="'+e(id)+'"':'')+'>'+label+'</button>';
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),6500);}
function notice(text,cls=''){return '<div class="notice '+cls+'">'+icon('info')+'<div>'+text+'</div></div>';}
function option(value,label,current){return '<option value="'+e(value)+'"'+(value===current?' selected':'')+'>'+e(label)+'</option>';}
function select(name,label,values,current='',empty='Todos'){return '<label>'+label+'<select name="'+name+'" id="'+name+'">'+(empty!==null?option('',empty,current):'')+values.map(x=>typeof x==='string'?option(x,x,current):option(x.id,x.name,current)).join('')+'</select></label>';}
