function areaOptions(){return [...(state.demoAreas||[]).filter(a=>showDemo),...state.areas.map(f=>f.properties)].filter(a=>(!filters.department||a.department===filters.department)&&(!filters.municipality||a.municipality===filters.municipality));}
function nameOf(code,kind='municipalities'){return T[kind].features.find(f=>f.properties.id===code)?.properties.name||code;}
function territoryName(f=filters){return f.area?(areaOptions().find(x=>x.id===f.area)?.name||f.area):f.municipality?nameOf(f.municipality):f.department?nameOf(f.department,'departments'):'Colombia';}
