async function saveEvidence(){
  const form=$('#evidence-form');if(!form.reportValidity())return;const fd=new FormData(form),old=state.evidence.find(r=>r.id===form.dataset.id),r={id:form.dataset.id};
  for(const k of ['title','question','population','alternative','outcomes','design','certainty','applicability','summary','reference','version','reviewer','reviewed','next_review'])r[k]=String(fd.get(k)||'').trim();
  for(const k of ['conditions','services','profiles'])r[k]=fd.getAll(k);r.status=fd.get('evidence-status');r.demo=fd.has('demo');
  if(['conditions','services','profiles'].some(k=>!r[k].length))return formError('Seleccione al menos una condición, un servicio y un perfil.');
  if(r.status==='Revisión registrada'&&(['reference','reviewer','population','alternative','outcomes','design','certainty','applicability','summary'].some(k=>!r[k])||!C.dateValid(r.reviewed)||!C.dateValid(r.next_review)||r.next_review<=r.reviewed||r.reviewed>C.today()))return formError('Complete la referencia, todos los campos de revisión y fechas válidas. La próxima revisión debe ser posterior; la revisión no puede estar en el futuro.');
  r.history=[...(old?.history||[]),{at:new Date().toISOString(),version:r.version,status:r.status,reviewer:r.reviewer,previous:old?Object.fromEntries(Object.entries(old).filter(([k])=>k!=='history')):null}];
  const next=C.clone(state),idx=next.evidence.findIndex(x=>x.id===r.id);if(idx<0)next.evidence.push(r);else next.evidence[idx]=r;await persist(next);closeDialog();renderView();toast('Ficha guardada.');
}
